/**
 * Shader du halo qui pulse.
 *
 * ## L'idee mathematique
 *
 * Un coeur gaussien qui respire au rythme d'une periode reglable, et des
 * anneaux emis a ce meme rythme : chacun est une gaussienne de la distance
 * au centre, dont le rayon croit avec sa phase, qui s'elargit et palit en
 * s'eloignant. Les anneaux se repartissent uniformement sur la periode, si
 * bien que l'emission est reguliere, jamais en rafale.
 *
 * Distinct du sonar, dont les fronts sont raides, suivent le pointeur et
 * laissent une traine sombre : ici tout est doux, lent, et pose par melange
 * borne vers les teintes.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le fond.
 * - `uColorB` — les anneaux et le halo.
 * - `uColorC` — le coeur.
 * - `uX`, `uY` — position du centre, en fraction du cadre.
 * - `uPeriod` — periode du rythme, en secondes.
 * - `uRings` — nombre d'anneaux en vol.
 * - `uSize` — portee des anneaux, en hauteurs de cadre.
 */
export const HALO_PULSE_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uX;
uniform float uY;
uniform float uPeriod;
uniform float uRings;
uniform float uSize;

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vec2(vUv.x * aspect, vUv.y);
  vec2 centre = vec2(uX * aspect, uY);
  float r = length(p - centre);

  float periode = max(uPeriod, 0.5);
  float portee = max(uSize, 0.1);
  int n = int(clamp(uRings, 1.0, 6.0));

  // Les anneaux : chacun decale d'une fraction de la periode, pour une
  // emission reguliere. Le rayon croit avec la phase ; la largeur aussi,
  // et l'intensite tombe au carre — un anneau meurt avant sa portee.
  float anneaux = 0.0;
  for (int i = 0; i < 6; i += 1) {
    if (i >= n) break;
    float phase = fract(uTime / periode + float(i) / float(n));
    float rayon = phase * portee;
    float largeur = 0.012 + 0.06 * phase;
    float e = (r - rayon) / largeur;
    float vie = 1.0 - phase;
    anneaux += exp(-e * e) * vie * vie;
  }

  // Le coeur respire au meme rythme : il grossit a l'emission.
  float souffle = 0.5 + 0.5 * sin(uTime / periode * 6.2831853);
  float coeur = exp(-r * r / (0.012 + 0.012 * souffle));
  float halo = exp(-r * (7.0 - 2.5 * souffle)) * 0.5;

  vec3 colour = mix(uColorA, uColorB, clamp(anneaux * 0.8 + halo * 0.6, 0.0, 1.0));
  colour = mix(colour, uColorC, clamp(coeur * (0.7 + 0.3 * souffle), 0.0, 1.0));

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Halo qui pulse : un coeur qui respire et des anneaux emis a un rythme lent.
 *
 * ## Le principe
 *
 * Des anneaux gaussiens dont le rayon croit avec leur phase, repartis
 * uniformement sur la periode pour une emission reguliere ; ils s'elargissent
 * et palissent en s'eloignant. Le coeur grossit a chaque emission. Distinct
 * du sonar, aux fronts raides et au pointeur : ici tout est doux et pose.
 *
 * ## Ce que ce composant delegue
 *
 * Il ne porte que ce qui le distingue : son shader, ses reglages et son repli.
 * La lecture des tokens, leur conversion en flottants et leur relecture au
 * changement de theme viennent du moteur.
 *
 * Le repli n'est pas une precaution : il est affiche pendant le chargement du
 * backend, quand WebGL manque, quand l'arbitre refuse la surface et sous
 * mouvement reduit.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { HALO_PULSE_FRAGMENT } from './halo-pulse.shader.js'

/** Ce que l'echappatoire recoit. */
export interface HaloPulseControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface HaloPulseOwnProps {
  /** Periode du rythme, en millisecondes. @defaultValue 4000 */
  period?: number
  /** Nombre d'anneaux en vol. @defaultValue 3 */
  rings?: number
  /** Portee des anneaux, en hauteurs de cadre. @defaultValue 0.8 */
  size?: number
  /** Position horizontale du centre, en fraction du cadre. @defaultValue 0.5 */
  x?: number
  /** Position verticale du centre, en fraction du cadre. @defaultValue 0.5 */
  y?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<HaloPulseControls>
}

/** Toutes les proprietes. */
export type HaloPulseProps = Customisable<HaloPulseOwnProps>

/** Tokens employes par defaut : le fond, les anneaux, le coeur. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-teal-400',
  '--o-palette-brand-500',
] as const

/** Repli par defaut : un degrade fige, dans les memes tons. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-br o-from-zinc-50 dark:o-from-zinc-950 o-to-teal-100 dark:o-to-teal-950'

/**
 * Halo qui pulse.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <HaloPulse className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function HaloPulse({
  period = 4000,
  rings = 3,
  size = 0.8,
  x = 0.5,
  y = 0.5,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: HaloPulseProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: HALO_PULSE_FRAGMENT,
    colors,
    // Le registre parle en millisecondes, le shader en secondes.
    uniforms: { uPeriod: period / 1000, uRings: rings, uSize: size, uX: x, uY: y },
    name: 'halo-pulse',
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
